const rows = $input.all().map(i => i.json);
const proj = rows[0] || {};
const total = rows.reduce((s, r) => s + Number(r.allocated_amount ?? 0), 0);
const lines = rows.filter(r => r.division_code).map(r => `<tr><td>${r.division_code ?? ''}</td><td>${r.scope_description ?? ''}</td><td>$${Number(r.allocated_amount ?? 0).toLocaleString('en-US')}</td></tr>`).join('');
const form = `<form method='POST' action='/webhook/estimate/approval'><input type='hidden' name='token' value='${proj.token ?? ''}'><input type='hidden' name='approval_method' value='onsite_link'><input type='text' name='signer_name' placeholder='Type your full name' required><br><button class='btn approve' name='decision' value='approve'>Approve</button><button class='btn reject' name='decision' value='reject'>Reject</button></form>`;
let body;
if (!proj.found) {
  body = `<p>This approval link is no longer valid - a newer request may have been sent. Please ask for the latest link.</p>`;
} else if (proj.baseline_status === 'SENT') {
  body = `<table><tr><th>Division</th><th>Scope</th><th>Amount</th></tr>${lines}</table><div class='total'>Total: $${total.toLocaleString('en-US')}</div>${form}`;
} else if (proj.baseline_status === 'CREATED') {
  body = `<p>This estimate has not been sent for approval yet.</p>`;
} else if (proj.baseline_status === 'APPROVED') {
  const when = proj.baseline_approved_at ? ' on ' + String(proj.baseline_approved_at).slice(0, 10) : '';
  const who = proj.baseline_approved_by ? (' by ' + proj.baseline_approved_by) : '';
  body = `<p>This baseline estimate is already approved${who}${when}.</p>`;
} else {
  body = `<p>This baseline estimate was rejected. A revised request can be sent later.</p>`;
}
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>Approve Estimate</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;max-width:640px}h1{font-size:1.4rem;color:#2563eb}table{width:100%;border-collapse:collapse}td,th{padding:.5rem;border-bottom:1px solid #e2e8f0;text-align:left}.total{font-size:1.3rem;font-weight:700;margin-top:1rem}input[type=text]{width:100%;padding:.6rem;margin:1rem 0;font-size:1rem;box-sizing:border-box}.btn{padding:.7rem 1.2rem;border:none;border-radius:6px;font-size:1rem;cursor:pointer;margin-right:.5rem}.approve{background:#16a34a;color:#fff}.reject{background:#dc2626;color:#fff}</style></head><body><h1>Baseline Estimate \u2014 ${proj.title ?? ''}</h1>${body}</body></html>`;
return [{ json: { html } }];

const r = $('Estimate Approval Update').first()?.json || $input.first()?.json;
const ok = r && r.baseline_status === 'APPROVED';
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>${ok ? 'Approved' : 'Decision recorded'}</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;text-align:center}.ok{color:#16a34a;font-size:1.5rem;font-weight:700}.no{color:#dc2626;font-size:1.5rem;font-weight:700}</style></head><body><div class='${ok ? 'ok' : 'no'}'>${ok ? 'Approved' : 'Decision recorded'}</div><p>${r?.title ?? ''}</p>${ok ? `<p>Revised contract: $${Number(r.revised_contract_value ?? 0).toLocaleString('en-US')}</p>` : ''}</body></html>`;
return [{ json: { html } }];

const co = $input.first()?.json;
const amount = Number(co?.cost_impact ?? 0);
const sign = amount >= 0 ? '+' : '';
const form = `<form method='POST' action='/webhook/change-order/approval'><input type='hidden' name='token' value='${co?.token ?? ''}'><input type='hidden' name='approval_method' value='onsite_link'><input type='text' name='signer_name' placeholder='Type your full name' required><br><button class='btn approve' name='decision' value='approve'>Approve</button><button class='btn reject' name='decision' value='reject'>Reject</button></form>`;
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>Approve Change Order</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;max-width:640px}h1{font-size:1.4rem;color:#2563eb}.amount{font-size:1.6rem;font-weight:700}.row{display:flex;justify-content:space-between;padding:.4rem 0;border-bottom:1px solid #e2e8f0}input[type=text]{width:100%;padding:.6rem;margin:1rem 0;font-size:1rem;box-sizing:border-box}.btn{padding:.7rem 1.2rem;border:none;border-radius:6px;font-size:1rem;cursor:pointer;margin-right:.5rem}.approve{background:#16a34a;color:#fff}.reject{background:#dc2626;color:#fff}</style></head><body><h1>Change Order #${co?.change_order_number ?? ''} — ${co?.project_name ?? ''}</h1><div class='row'><span>Description</span><span>${co?.description ?? ''}</span></div><div class='row'><span>Impact</span><span class='amount'>${sign}$${Math.abs(amount).toLocaleString('en-US')}</span></div>${co?.approval_status === 'PENDING' ? form : `<p>This change order is already ${(co?.approval_status ?? '').toLowerCase()}.</p>`}</body></html>`;
return [{ json: { html } }];

const r = $input.first()?.json;
const ok = r && r.approval_status === 'APPROVED';
const html = `<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width, initial-scale=1'><title>${ok ? 'Approved' : 'Decision recorded'}</title><style>body{font-family:Helvetica,Arial,sans-serif;color:#1e293b;margin:2rem;text-align:center}.ok{color:#16a34a;font-size:1.5rem;font-weight:700}.no{color:#dc2626;font-size:1.5rem;font-weight:700}</style></head><body><div class='${ok ? 'ok' : 'no'}'>${ok ? 'Approved' : 'Decision recorded'}</div><p>Change order #${r?.change_order_number ?? ''} — ${r?.title ?? ''}</p>${ok ? `<p>Revised contract: $${Number(r.revised_contract_value ?? 0).toLocaleString('en-US')}</p>` : ''}</body></html>`;
return [{ json: { html } }];

// PM notice on an estimate decision (approve/reject by the customer).
// Pushes {type:'notice', title, body} to every registered device so the app
// can show a plain notification. Suppressed when the signer looks automated
// ('QA ...'/'... Robot') so E2E runs do not spam the phone; the decision is
// still logged downstream.
const upd = $('Estimate Approval Update').first()?.json;
if (!upd || !upd.id) return []; // stale-token replay: nothing decided
const wbNode = $('Estimate Approval Action').first().json;
const body = (wbNode && wbNode.body) || wbNode || {};
const decision = String(body.decision || 'approve');
const signer = String(body.signer_name || '').trim();
const method = String(body.approval_method || 'onsite_link');
const status = String(upd.baseline_status || '');
const automated = /^qa[\s_]/i.test(signer) || /robot/i.test(signer);
const total = Number(upd.revised_contract_value || 0);

let pushed = 0;
let pushNote = '';
if (!automated) {
  const tokens = $input.all().map(i => i.json).filter(r => r && r.token).map(r => r.token);
  let saRaw = String($env.FCM_SERVICE_ACCOUNT_JSON || '').trim();
  if (!saRaw) {
    try {
      const file = String($env.FCM_SERVICE_ACCOUNT_FILE || '').trim();
      if (file) saRaw = require('fs').readFileSync(file, 'utf8').trim();
    } catch (e) {
      pushNote = 'key file read failed: ' + e.message;
    }
  }
  if (!saRaw) {
    pushNote = pushNote || 'FCM not configured; push skipped';
  } else if (tokens.length === 0) {
    pushNote = 'no registered devices';
  } else {
    try {
      const sa = JSON.parse(saRaw);
      const crypto = require('crypto');
      const accessToken = await getAccessToken(sa, crypto);
      const title = status === 'APPROVED' ? 'Estimate approved' : 'Estimate rejected';
      const text = `${upd.title}: $${total.toLocaleString('en-US')}${status === 'APPROVED' ? ' signed by ' + (signer || 'customer') : ''}.`;
      for (const token of tokens) {
        try {
          await sendFcm(accessToken, sa.project_id, token, { type: 'notice', title, body: text });
          pushed++;
        } catch (e) {
          // stale/NotRegistered tokens must not abort the rest (same rule as
          // the gateway push nodes).
        }
      }
      pushNote = 'pushed to ' + pushed + ' device(s)';
    } catch (e) {
      pushNote = 'FCM send failed: ' + e.message;
    }
  }
} else {
  pushNote = 'automation signer - push suppressed';
}

return [{ json: {
  project_id: String(upd.id),
  kind: status === 'APPROVED' ? 'estimate_approved' : 'estimate_rejected',
  log_note: `signer=${signer || '-'}; method=${method}; ${pushNote}`,
} }];

function b64url(s) {
  return s.replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}
function splitUrl(u) {
  const m = u.match(/^https?:\/\/([^/]+)(\/[^?#]*)?(\?[^#]*)?/);
  return { hostname: m[1], path: (m[2] || '/') + (m[3] || '') };
}
function httpsRequest(options, body) {
  return new Promise((resolve, reject) => {
    const req = require('https').request(options, (res) => {
      let data = '';
      res.on('data', (c) => (data += c));
      res.on('end', () => resolve({ status: res.statusCode, body: data }));
    });
    req.on('error', reject);
    req.write(body);
    req.end();
  });
}
async function getAccessToken(sa, crypto) {
  const now = Math.floor(Date.now() / 1000);
  const head = b64url(Buffer.from(JSON.stringify({ alg: 'RS256', typ: 'JWT' })).toString('base64'));
  const claim = b64url(Buffer.from(JSON.stringify({
    iss: sa.client_email,
    scope: 'https://www.googleapis.com/auth/firebase.messaging',
    aud: sa.token_uri,
    iat: now,
    exp: now + 3600
  })).toString('base64'));
  const input = head + '.' + claim;
  const sig = b64url(crypto.createSign('RSA-SHA256').update(input).sign(sa.private_key).toString('base64'));
  const jwt = input + '.' + sig;
  const u = splitUrl(sa.token_uri);
  const resp = await httpsRequest({
    method: 'POST',
    hostname: u.hostname,
    path: u.path,
    headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
  }, 'grant_type=urn:ietf:params:oauth:grant-type:jwt-bearer&assertion=' + encodeURIComponent(jwt));
  const parsed = JSON.parse(resp.body);
  if (!parsed.access_token) {
    throw new Error('token exchange failed (' + resp.status + '): ' + resp.body.slice(0, 200));
  }
  return parsed.access_token;
}
async function sendFcm(accessToken, projectId, token, data) {
  const u = splitUrl('https://fcm.googleapis.com/v1/projects/' + projectId + '/messages:send');
  const resp = await httpsRequest({
    method: 'POST',
    hostname: u.hostname,
    path: u.path,
    headers: { 'Content-Type': 'application/json', 'Authorization': 'Bearer ' + accessToken },
  }, JSON.stringify({ message: { token, data } }));
  if (resp.status >= 400) {
    throw new Error('FCM HTTP ' + resp.status + ': ' + resp.body.slice(0, 200));
  }
}

